  else if (type === 'car') fee = hours * 20;
  else if (type === 'truck') fee = hours * 50;
  else if (type === 'ev') {
    if (chargingSpots.includes(spot)) fee = hours * 30;
    else fee = hours * 20;
  }
  console.log('QUOTE ' + plate + ' FEE ' + fee);
}

